            path: {
                /** @description A discussion reference, parsed leniently — `DSC-0007`, `dsc-7`, `DSC-00007` all name thread 7 — and rendered strictly as `DSC-0007`. */
                ref: components["parameters"]["DiscussionRef"];
            };
